PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "jugadas_jugada" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "numero" varchar(20) NOT NULL, "monto" decimal NOT NULL, "fecha" datetime NOT NULL, "fecha_sorteo" date NULL, "estado" varchar(25) NOT NULL, "monto_premio" decimal NULL, "sobrelimite" bool NOT NULL, "saldo_antes" decimal NULL, "saldo_despues" decimal NULL, "modificado_en" datetime NULL, "creado_en" datetime NOT NULL, "actualizado_en" datetime NOT NULL, "metadata" text NOT NULL CHECK ((JSON_VALID("metadata") OR "metadata" IS NULL)), "autorizada_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "comercial_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "destinatario_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "forma_juego_id" bigint NOT NULL REFERENCES "jugadas_formajuego" ("id") DEFERRABLE INITIALLY DEFERRED, "forma_pago_id" bigint NULL REFERENCES "pagos_formapago" ("id") DEFERRABLE INITIALLY DEFERRED, "modificado_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "sorteo_id" bigint NOT NULL REFERENCES "sorteos_sorteo" ("id") DEFERRABLE INITIALLY DEFERRED, "usuario_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "boleta_id" bigint NULL REFERENCES "jugadas_boleta" ("id") DEFERRABLE INITIALLY DEFERRED);
COMMIT;
